export function factorial(n: number): any {
  let res, i;
  res = 1;
  for (i=2; i<=n; i++) {
    res = res*i;
  }
  return res;
}
export function isEven(n: number): boolean {
  return (n%2===0);
}
export function sumTo(n: number): any {
  let total, i;
  total = 0;
  for (i=1; i<=n; i++) {
    total = total+i;
  }
  return total;
}
export function square(n: number): any {
  return n*n;
}
export function double(n: number): any {
  return n+n;
}